#include <string>
#include <algorithm>

class Solution {
public:
    std::string rearrangeToAvoidPair(std::string s, std::string forbidden) {
        std::string res = s;
        std::sort(res.rbegin(), res.rend());
        if (res.find(forbidden) != std::string::npos) {
            std::sort(res.begin(), res.end());
        }
        return (res.find(forbidden) == std::string::npos) ? res : "";
    }
};

import java.util.*;

class Solution {
    public String rearrangeToAvoidPair(String s, String forbidden) {
        Character[] chars = new Character[s.length()];
        for (int i = 0; i < s.length(); i++) chars[i] = s.charAt(i);
        Arrays.sort(chars, Collections.reverseOrder());
        StringBuilder sb = new StringBuilder();
        for (char c : chars) sb.append(c);
        String res = sb.toString();
        if (res.contains(forbidden)) {
            Arrays.sort(chars);
            sb = new StringBuilder();
            for (char c : chars) sb.append(c);
            res = sb.toString();
        }
        return res.contains(forbidden) ? "" : res;
    }
}

